CREATE COLUMN TABLE "TEST_AP"."OBRW" ("AbsEntry" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "Type" SMALLINT CS_INT DEFAULT 0, "Url" NVARCHAR(254), "App" NVARCHAR(100), "Title" NVARCHAR(254), "ShowWebTil" NVARCHAR(1) DEFAULT 'N', "Size" NVARCHAR(15), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBRW_NAME" ON "TEST_AP"."OBRW" ( "Name" ASC )